/* ============================================================
   ЛУЧИ — дашборд о2о встреч
   Токены бренда: палитра из 7 цветов, Cera Condensed + Styrene A.
   Раскладка (grid/flex/размеры) прежняя — меняется только оформление.
   ============================================================ */
@font-face{font-family:'Cera Condensed';font-weight:900;font-style:normal;font-display:swap;src:url(https://raw.githubusercontent.com/d00872948-bot/my-assets/luchi-fonts/luchi-fonts/Cera_Condensed-Black.woff) format('woff');}
@font-face{font-family:'Cera Condensed';font-weight:500;font-style:normal;font-display:swap;src:url(https://raw.githubusercontent.com/d00872948-bot/my-assets/luchi-fonts/luchi-fonts/Cera_Condensed-Medium.woff) format('woff');}
@font-face{font-family:'Styrene A';font-weight:400;font-style:normal;font-display:swap;src:url(https://raw.githubusercontent.com/d00872948-bot/my-assets/luchi-fonts/luchi-fonts/Styrene_A-Regular.woff) format('woff');}
@font-face{font-family:'Styrene A';font-weight:500;font-style:normal;font-display:swap;src:url(https://raw.githubusercontent.com/d00872948-bot/my-assets/luchi-fonts/luchi-fonts/Styrene_A-Medium.woff) format('woff');}

:root {
  /* палитра бренда — ровно 7 цветов */
  --coral: #FF7377;
  --sky:   #078EFF;
  --teal:  #026B83;
  --ice:   #71D7FF;
  --sand:  #EFEBCC;
  --ink:   #022028;
  --white: #FFFFFF;

  --font-display: 'Cera Condensed', 'Arial Narrow', sans-serif;
  --font-body: 'Styrene A', 'Helvetica Neue', Arial, sans-serif;

  /* производные — только прозрачности палитры */
  --card: rgba(2, 32, 40, .92);
  --card-soft: rgba(255, 255, 255, .06);
  --line: rgba(255, 255, 255, .14);
  --muted: rgba(255, 255, 255, .68);
  --radius: 20px;

  /* совместимость со старыми именами переменных */
  --bg-color: var(--ink);
  --card-bg: var(--card);
  --card-border: var(--line);
  --text-main: var(--white);
  --text-muted: var(--muted);
  --accent: var(--ice);
  --accent-hover: var(--coral);
  --success: var(--ice);
  --warning: var(--sand);
  --danger: var(--coral);
}

/* ===== ЗАСТАВКА: тёмная база, сборка логотипа и «полёт» в шапку ===== */
#loader-overlay {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  background: var(--ink);
  z-index: 9998;
  opacity: 1;
  visibility: visible;
  transition: opacity .9s ease-in-out, visibility 0s linear .9s;
}

#loader-overlay.hide {
  opacity: 0;
  visibility: hidden;
}

#animated-logo-container {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  z-index: 9999;
}

.luchi-svg {
  height: 120px;
  color: var(--coral);
  transform-origin: 0 0;
  transition: transform 1.1s cubic-bezier(0.77, 0, 0.175, 1);
}

.luchi-svg path {
  opacity: 0;
  animation: assembleParts 1.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  transform-origin: center;
}

.luchi-svg path:nth-child(1) { transform: translate(-100px, -50px) rotate(-90deg) scale(0.5); animation-delay: 0.05s; }
.luchi-svg path:nth-child(2) { transform: translate(50px, -80px) rotate(45deg) scale(0.5); animation-delay: 0.20s; }
.luchi-svg path:nth-child(3) { transform: translate(-60px, 80px) rotate(-45deg) scale(0.5); animation-delay: 0.12s; }
.luchi-svg path:nth-child(4) { transform: translate(80px, 50px) rotate(90deg) scale(0.5); animation-delay: 0.28s; }
.luchi-svg path:nth-child(5) { transform: translate(0, -100px) rotate(180deg) scale(0.5); animation-delay: 0.36s; }
.luchi-svg path:nth-child(6) { transform: translate(100px, 0) scale(0.2); animation-delay: 0.44s; }
.luchi-svg path:nth-child(7) { transform: translate(-100px, 0) scale(0.2); animation-delay: 0.52s; }
.luchi-svg path:nth-child(8) { transform: translateY(50px) scale(0.1); animation-delay: 0.60s; }

@keyframes assembleParts {
  to { opacity: 1; transform: translate(0, 0) rotate(0) scale(1); }
}

.luchi-text {
  color: var(--sand);
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 40px;
  line-height: .9;
  text-transform: uppercase;
  letter-spacing: 0;
  margin: 0;
  padding-left: 5px;
  opacity: 0;
  transform: translateY(30px);
  animation: textFadeIn .8s ease-out forwards;
  animation-delay: 1.15s;
}

/* когда логотип улетает в шапку, надпись гаснет */
#animated-logo-container.finished .luchi-text {
  opacity: 0 !important;
  transition: opacity .35s ease;
}

@keyframes textFadeIn {
  to { opacity: 1; transform: translateY(0); }
}

#dashboard-content {
  opacity: 0;
  visibility: hidden;
  transition: opacity .9s ease-in-out;
}

#dashboard-content.visible {
  opacity: 1;
  visibility: visible;
}

/* страховка: если скрипт заставки не отработал, страница всё равно появится */
#dashboard-content { animation: forceShow 0s linear 8s forwards; }
#loader-overlay { animation: forceHide 0s linear 8s forwards; }
@keyframes forceShow { to { opacity: 1; visibility: visible; } }
@keyframes forceHide { to { opacity: 0; visibility: hidden; } }

/* повторный заход в этой вкладке (или «уменьшить анимацию»): без заставки */
.intro-skip #loader-overlay,
.intro-skip #animated-logo-container { display: none; }
.intro-skip #dashboard-content { opacity: 1; visibility: visible; transition: none; animation: none; }
.intro-skip .reveal-item { opacity: 1; transform: none; transition: none; }
.intro-skip .hdr-logo,
.intro-skip .brand .prod { opacity: 1; }

/* появление блоков после заставки */
.reveal-item {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .7s ease, transform .7s cubic-bezier(.16, 1, .3, 1);
}

#dashboard-content.visible .reveal-item {
  opacity: 1;
  transform: none;
}

#dashboard-content.visible .reveal-item:nth-child(2) { transition-delay: .10s; }
#dashboard-content.visible .reveal-item:nth-child(3) { transition-delay: .18s; }
#dashboard-content.visible .reveal-item:nth-child(4) { transition-delay: .26s; }
#dashboard-content.visible .reveal-item:nth-child(5) { transition-delay: .34s; }

@media (prefers-reduced-motion: reduce) {
  .reveal-item { opacity: 1; transform: none; transition: none; }
  #dashboard-content, #loader-overlay, #animated-logo-container { transition-duration: .01s; }
}

/* ===== БАЗА ===== */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: var(--font-body);
}

body {
  --gap: clamp(16px, 2.6vw, 36px);
  position: relative;
  background-color: var(--sky) !important;
  background-image:
    url('https://github.com/d00872948-bot/my-assets/blob/main/rf1l6e2nbue8x5nh.jpg?raw=true'),
    radial-gradient(900px 520px at 78% 0%, rgba(113, 215, 255, .5), transparent 62%) !important;
  background-size: cover, auto !important;
  background-position: center, center !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
  color: var(--text-main);
  padding: 0 var(--gap) 28px;
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2, h3, h4 {
  font-family: var(--font-display);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0;
  line-height: 1;
}

/* шапка: коралловая лента, как в «Мониторинге линий» и «Нейронаставнике» */
.topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  margin: 0 calc(var(--gap) * -1) 24px;
  background: rgba(2, 32, 40, .92);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid rgba(255, 255, 255, .12);
  color: var(--sand);
}

.topbar-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-height: 0;
  padding: 14px var(--gap);
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--sand);
  text-decoration: none;
  min-width: 0;
}

.hdr-logo {
  height: 26px;
  width: auto;
  flex: none;
  color: var(--coral);
  opacity: 0;
  transition: opacity .15s ease;
}

.brand .prod {
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 19px;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--sand);
  padding-left: 14px;
  border-left: 1px solid rgba(255, 255, 255, .2);
  opacity: 0;
  transition: opacity .5s ease .1s;
  white-space: nowrap;
}

body.docked .hdr-logo,
body.docked .brand .prod { opacity: 1; }

/* страховка для логотипа и названия в шапке */
.hdr-logo, .brand .prod { animation: hdrShow 0s linear 8s forwards; }
@keyframes hdrShow { to { opacity: 1; } }

.topbar .tagline {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: .16em;
  color: var(--sand);
}

.topbar .tagline svg {
  width: 18px;
  height: 18px;
  color: var(--coral);
  flex: none;
}

.header { margin-bottom: 24px; }
.title h1 { font-size: 28px; }
.title p { color: var(--text-muted); font-size: 14px; margin-top: 4px; }

/* ===== КАРТОЧКИ СВЕРХУ ===== */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 28px;
}

.stat-card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px 22px;
  box-shadow: 0 14px 34px rgba(2, 32, 40, .22);
}

.stat-card > div:first-child {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 13px !important;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--sand) !important;
}

.stat-card .num {
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 44px;
  line-height: .9;
  margin-top: 12px;
  text-transform: uppercase;
}

.stat-card.total .num,
.stat-card.match .num { color: var(--coral) !important; }

/* ===== СТАТИСТИКА ПО НАПРАВЛЕНИЯМ ===== */
.team-stats-title {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin: 6px 0 14px;
}

.team-stats-title h2 {
  color: var(--white);
  font-size: 34px;
  text-shadow: 0 2px 14px rgba(2, 32, 40, .35);
}

.team-stats-title span { color: var(--white); font-size: 13px; }

.team-stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 14px;
  margin-bottom: 28px;
}

.team-stat-card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px 22px;
  box-shadow: 0 14px 34px rgba(2, 32, 40, .22);
  transition: transform .2s ease, border-color .2s ease;
}

.team-stat-card:hover { transform: translateY(-3px); border-color: var(--coral); }

.team-stat-name {
  color: var(--sand);
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 22px;
  text-transform: uppercase;
  line-height: 1;
  min-height: 40px;
  margin-bottom: 14px;
}

.team-stat-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  padding-top: 10px;
  margin-top: 10px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 13px;
}

.team-stat-line strong {
  color: var(--white);
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 24px;
  line-height: 1;
}

.team-stat-line .team-meetings-count {
  color: var(--coral);
  font-size: 28px;
}

/* ===== РАЗДЕЛИТЕЛЬ НАПРАВЛЕНИЙ В ТАБЛИЦЕ ===== */
.department-section-row td {
  padding: 0 !important;
  background: var(--ink) !important;
  border-bottom: 0 !important;
}

.department-section {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-top: 0;
  padding: 14px 18px;
  background: var(--coral);
  border-bottom: 1px solid var(--line);
}

.department-section-name {
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 24px;
  text-transform: uppercase;
  line-height: 1;
}

.department-section-info {
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 13px;
  letter-spacing: .1em;
  text-transform: uppercase;
  text-align: right;
}

.department-section-info strong {
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 20px;
}

/* ===== ПОИСК И ТАБЛИЦА ===== */
.controls {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
}

.search-input {
  width: 100%;
  background: var(--white);
  border: 1px solid transparent;
  color: var(--ink);
  padding: 14px 22px;
  border-radius: 100px;
  font-size: 15px;
  outline: none;
  box-shadow: 0 10px 26px rgba(2, 32, 40, .18);
}

.search-input::placeholder { color: rgba(2, 32, 40, .55); }

.search-input:focus {
  border-color: var(--coral);
  box-shadow: 0 0 0 3px rgba(255, 115, 119, .55), 0 10px 26px rgba(2, 32, 40, .18);
}

.table-container {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow-x: auto;
  box-shadow: 0 14px 34px rgba(2, 32, 40, .22);
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 14px;
}

th {
  background: var(--ink);
  color: var(--ice);
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: .14em;
  padding: 16px;
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
}

td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
  vertical-align: middle;
}

tr:hover { background: rgba(113, 215, 255, .08); }

.muted-small { color: var(--muted); font-size: 12px; }

.o2o-date {
  display: inline-block;
  min-width: 145px;
  line-height: 1.4;
}

.next-o2o { color: var(--ice); }

.warn-mini { font-size: 11px; color: var(--coral); }

.tracker-link {
  color: var(--ice);
  text-decoration: none;
  font-weight: 500;
}

.tracker-link:hover { text-decoration: underline; color: var(--white); }

/* ===== КНОПКИ ===== */
.btn-action,
.btn-summary,
.btn-secondary,
.btn-o2o-cheatsheet {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: .1em;
  border-radius: 100px;
  padding: 10px 18px;
  cursor: pointer;
  white-space: nowrap;
  transition: transform .12s ease, background .2s ease, color .2s ease, box-shadow .2s ease;
}

.btn-action {
  background: var(--coral);
  color: var(--white);
  border: 1px solid var(--coral);
  box-shadow: 0 8px 18px rgba(255, 115, 119, .28);
}

.btn-action:hover {
  transform: translateY(-1px);
  background: var(--white);
  color: var(--coral);
}

.action-buttons {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.btn-summary {
  background: transparent;
  color: var(--ice);
  border: 1px solid var(--ice);
}

.btn-summary:hover {
  transform: translateY(-1px);
  background: var(--ice);
  color: var(--ink);
}

.btn-summary:disabled { opacity: .5; cursor: not-allowed; }
.btn-action:disabled { opacity: .5; cursor: not-allowed; }

.btn-action:active, .btn-summary:active, .btn-secondary:active { transform: scale(.97); }

/* ===== МОДАЛЬНЫЕ ОКНА ===== */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(2, 32, 40, .72);
  display: none;
  justify-content: center;
  align-items: center;
  z-index: 1000;
  backdrop-filter: blur(6px);
}

.modal {
  background: var(--ink);
  border: 1px solid var(--line);
  width: 100%;
  max-width: 580px;
  border-radius: 28px;
  padding: 28px;
  max-height: 92vh;
  overflow-y: auto;
  box-shadow: 0 30px 80px rgba(2, 32, 40, .5);
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
  border-bottom: 1px solid var(--line);
  padding-bottom: 14px;
}

.modal-header h2,
.modal-header h3 {
  color: var(--sand);
  font-size: 28px;
}

.modal-close {
  cursor: pointer;
  color: var(--muted);
  font-size: 26px;
  line-height: 1;
  width: 38px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--card-soft);
  transition: background .2s ease, color .2s ease;
}

.modal-close:hover { color: var(--white); background: rgba(255, 115, 119, .35); }

.form-group { margin-bottom: 14px; }

.form-group label {
  display: block;
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--sand);
  margin-bottom: 7px;
}

.form-control {
  width: 100%;
  background: var(--white);
  border: 1px solid transparent;
  border-radius: 16px;
  color: var(--ink);
  padding: 12px 16px;
  font-size: 14px;
  outline: none;
}

.form-control:focus {
  border-color: var(--coral);
  box-shadow: 0 0 0 3px rgba(255, 115, 119, .45);
}

.form-row { display: flex; gap: 12px; }
.form-row .form-group { flex: 1; }

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
  border-top: 1px solid var(--line);
  padding-top: 16px;
}

.btn-secondary {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--white);
}

.btn-secondary:hover { background: var(--card-soft); border-color: var(--ice); }

.status-msg {
  font-size: 13px;
  margin-top: 8px;
  display: none;
  padding: 10px 14px;
  border-radius: 14px;
  white-space: pre-wrap;
}

.status-msg.success {
  background: rgba(113, 215, 255, .16);
  color: var(--ice);
}

.status-msg.error {
  background: rgba(255, 115, 119, .18);
  color: var(--coral);
}

#availabilityBox {
  background: var(--card-soft);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 12px;
  margin-bottom: 14px;
}

#availabilityBox .ab-title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--muted);
  margin-bottom: 8px;
}

#availabilityBox .ab-lunch {
  font-size: 12px;
  color: var(--sand);
  margin-bottom: 8px;
}

.slot-grid { display: flex; flex-wrap: wrap; gap: 6px; }

.slot {
  background: rgba(113, 215, 255, .14);
  color: var(--ice);
  border: 1px solid transparent;
  border-radius: 100px;
  padding: 6px 12px;
  font-size: 12px;
  cursor: pointer;
  transition: background .15s ease;
}

.slot:hover { background: rgba(113, 215, 255, .28); }

.slot.active {
  background: var(--coral);
  color: var(--white);
  font-weight: 500;
}

.no-slots { font-size: 12px; color: var(--coral); }

/* ===== ШПАРГАЛКА «ИТОГИ O2O» ===== */
.btn-o2o-cheatsheet {
  background: var(--sky);
  border: 1px solid var(--sky);
  color: var(--white);
}

.btn-o2o-cheatsheet:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 20px rgba(7, 142, 255, .4);
}

#o2oCheatsheetModal {
  z-index: 1100;
  padding: 20px;
}

#o2oCheatsheetModal .o2o-cheatsheet-dialog {
  width: min(100%, 1040px);
  max-height: 90vh;
  overflow-y: auto;
  background: var(--ink);
  border: 1px solid var(--line);
  border-radius: 28px;
  padding: 28px;
  box-shadow: 0 30px 80px rgba(2, 32, 40, .5);
}

.o2o-cheatsheet-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 30px;
  color: var(--sand);
}

.o2o-cheatsheet-intro {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.5;
  margin: -6px 0 18px;
}

.o2o-cheatsheet-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.o2o-cheatsheet-card {
  background: var(--card-soft);
  border: 1px solid var(--line);
  border-left: 4px solid var(--ice);
  border-radius: 18px;
  padding: 18px;
}

.o2o-cheatsheet-card h4 {
  color: var(--white);
  font-size: 20px;
  margin-bottom: 10px;
}

.o2o-cheatsheet-card ul {
  color: var(--muted);
  padding-left: 18px;
  font-size: 13px;
  line-height: 1.55;
}

.o2o-cheatsheet-card li::marker { color: var(--coral); }
.o2o-cheatsheet-card li + li { margin-top: 5px; }

.o2o-cheatsheet-card--highlight { border-left-color: var(--sand); }
.o2o-cheatsheet-card--finish { border-left-color: var(--coral); }

.o2o-cheatsheet-footer {
  display: flex;
  justify-content: flex-end;
  margin-top: 18px;
}

/* ===== ПОДПИСЬ АВТОРА ===== */
.sign {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-top: 28px;
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--white);
  text-shadow: 0 1px 8px rgba(2, 32, 40, .45);
}

.sign svg { width: 16px; height: 16px; color: var(--coral); flex: none; }

/* ===== ТЕЛЕФОН ===== */
@media (max-width: 700px) {
  #o2oCheatsheetModal { align-items: flex-start; padding: 10px; }

  #o2oCheatsheetModal .o2o-cheatsheet-dialog {
    max-height: calc(100vh - 20px);
    padding: 18px;
  }

  .o2o-cheatsheet-title { font-size: 24px; }

  .o2o-cheatsheet-grid { grid-template-columns: 1fr; gap: 10px; }

  .o2o-cheatsheet-card { padding: 14px; }

  #summaryModal .modal-footer { flex-wrap: wrap; }

  .btn-o2o-cheatsheet { width: 100%; order: -1; }
}

@media (max-width: 700px) {
  body { padding: 0 12px 20px; --gap: 12px; }

  .topbar-row { padding-top: 12px; padding-bottom: 12px; }
  .hdr-logo { height: 22px; }
  .brand .prod { font-size: 15px; padding-left: 10px; }
  .topbar .tagline { display: none; }

  .luchi-svg { height: 84px; }
  .luchi-text { font-size: 26px; }

  .form-row { flex-direction: column; gap: 0; }

  .modal { width: calc(100% - 20px); padding: 18px; }

  .team-stats-title { display: block; }
  .team-stats-title h2 { margin-bottom: 5px; font-size: 28px; }
  .team-stats-title span { display: block; margin-top: 4px; }

  .team-stats-grid { grid-template-columns: 1fr; }

  .department-section { display: block; }
  .department-section-name { margin-bottom: 6px; }
  .department-section-info { text-align: left; line-height: 1.5; }

  .table-container { overflow-x: auto; }
  table { min-width: 900px; }
}

/* Запрет горизонтального растягивания полей в модальных окнах */
#summaryModal textarea,
#osModal textarea {
  display: block !important;
  box-sizing: border-box !important;
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
  resize: vertical !important;
  overflow-x: hidden !important;
}

/* Ограничение содержимого самих модальных окон */
#summaryModal,
#osModal {
  max-width: 100vw !important;
  overflow-x: hidden !important;
}

#summaryModal.modal-content,
#summaryModal.modal-body,
#osModal.modal-content,
#osModal.modal-body {
  box-sizing: border-box !important;
  max-width: 100% !important;
  min-width: 0 !important;
  overflow-x: hidden !important;
}

/* Увеличенная модалка «Итоги О2О» */
#summaryModal.modal-content,
#summaryModal > div {
  width: 95% !important;
  max-width: 1700px !important;
  max-height: 90vh !important;
  overflow-y: auto !important;
}

@media (max-width: 768px) {
  #summaryModal.modal-content,
  #summaryModal > div {
    width: 100% !important;
    max-width: 100% !important;
    max-height: 95vh !important;
  }
}

.o2o-frequency-list { margin: 0 0 20px; padding-left: 22px; }
.o2o-frequency-list li { margin-bottom: 6px; }
